def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    n = int(data[0])
    NEG = -10**30

    best_odd = NEG   # max sum of a valid kept sequence ending at an odd index
    best_even = NEG  # max sum of a valid kept sequence ending at an even index

    for i in range(1, n + 1):
        a = int(data[i])

        if i & 1:  # 1-based odd index
            cand = a
            if best_even != NEG:
                cand = max(cand, best_even + a)
            best_odd = max(best_odd, cand)
        else:      # 1-based even index
            if best_odd != NEG:
                best_even = max(best_even, best_odd + a)

    if n & 1:
        print(best_odd)
    else:
        print(max(0, best_even))

if __name__ == "__main__":
    main()

import sys

def main():
    S = sys.stdin.buffer.readline().strip()
    n = len(S)
    if n == 0:
        return

    R = S[::-1]

    # Prefix function for the pattern R
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        ri = R[i]
        while j > 0 and ri != R[j]:
            j = pi[j - 1]
        if ri == R[j]:
            j += 1
        pi[i] = j

    # KMP scan: longest prefix of R that is a suffix of S
    j = 0
    for c in S:
        while j > 0 and c != R[j]:
            j = pi[j - 1]
        if c == R[j]:
            j += 1

    # j is the length of the longest palindromic suffix of S
    ans = S + S[:n - j][::-1]
    sys.stdout.buffer.write(ans + b"\n")

if __name__ == "__main__":
    main()

