        return

    n = data[0]
    idx = 1
    dice = []

    for _ in range(n):
        k = data[idx]
        idx += 1
        cnt = {}
        for _ in range(k):
            a = data[idx]
            idx += 1
            cnt[a] = cnt.get(a, 0) + 1
        dice.append((k, cnt, list(cnt.items())))

    dice.sort(key=lambda x: len(x[1]))

    ans = 0.0

    for i in range(n):
        ki, _, items_i = dice[i]
        for j in range(i + 1, n):
            kj, cj, _ = dice[j]
            get = cj.get
            dot = 0

            for value, count in items_i:
                other_count = get(value)
                if other_count is not None:
                    dot += count * other_count

            if dot:
                prob = dot / (ki * kj)
                if prob > ans:
                    ans = prob

    print(f"{ans:.15f}")

if __name__ == "__main__":
