import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    R = int(data[1])
    C = int(data[2])
    S = data[3]

    offset = 2 * N + 1
    base = 4 * N + 3

    def encode(r, c):
        return (r + offset) * base + (c + offset)

    seen = set()
    seen.add(encode(0, 0))

    r = c = 0
    ans = []

    for ch in S:
        if ch == 'N':
            r -= 1
        elif ch == 'S':
            r += 1
        elif ch == 'W':
            c -= 1
        else:  # 'E'
            c += 1

        if encode(r - R, c - C) in seen:
            ans.append('1')
        else:
            ans.append('0')

        seen.add(encode(r, c))

    sys.stdout.write(''.join(ans) + '\n')

if __name__ == "__main__":
    main()
